INSERT INTO stayora.properties (id, host_id, title, destination, category, description, image_urls, amenities, badge, latitude, longitude, capacity, bedrooms, bathrooms, nightly_price, cleaning_fee, service_fee, rating, review_count, status, archived) VALUES
  ('11000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'Dar Yasmin and its blue courtyard', 'Sidi Bou Said', 'Guesthouses / Dars', 'A traditional courtyard home with patterned tiles, a shaded sitting area and two restful bedrooms. Make breakfast in the kitchen, then settle onto the terrace with a book. The home suits guests who enjoy a quiet base for exploring the village.', 'https://images.pexels.com/photos/36156108/pexels-photo-36156108.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Breakfast|Courtyard', 'COURTYARD LIVING', '36.871', '10.347', '4', '2', '2', '230', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'Sea breeze apartment in La Marsa', 'La Marsa, Tunis', 'Apartments', 'A bright one-bedroom apartment with a comfortable living room and a compact kitchen. A balcony catches the afternoon breeze, while a dedicated desk offers space to plan your day. A relaxed choice for a couple or a solo stay.', 'https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Dedicated workspace', 'ROOM TO UNWIND', '36.884', '10.326', '2', '1', '1', '155', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000002', 'Gammarth garden villa with pool', 'Gammarth', 'Houses', 'Spend slow afternoons beside the private pool and enjoy meals under the garden pergola. Three bedrooms, a family kitchen and a generous living area give everyone room to unwind. Parking is available inside the property.', 'https://images.pexels.com/photos/24807128/pexels-photo-24807128.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Pool|Free parking|Garden', 'ROOM TO UNWIND', '36.918', '10.296', '6', '3', '2', '390', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000002', 'Carthage artist studio', 'Carthage', 'Apartments', 'A characterful studio with warm wood, a reading corner and a small dining space. The kitchenette is equipped for simple meals. This is a cosy base for independent travellers who enjoy art, books and unhurried mornings.', 'https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Dedicated workspace', 'ROOM TO UNWIND', '36.853', '10.323', '2', '1', '1', '145', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000002', 'The lemon house in Hammamet', 'Hammamet', 'Houses', 'A welcoming two-bedroom house arranged around a sheltered outdoor dining area. Prepare local produce in the kitchen, relax in the living room and enjoy the terrace in the evening. The enclosed garden offers a quiet place to pause.', 'https://images.pexels.com/photos/38326661/pexels-photo-38326661.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Garden', 'ROOM TO UNWIND', '36.402', '10.613', '4', '2', '2', '265', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000002', 'Bizerte harbour hideaway', 'Bizerte', 'Apartments', 'A comfortable apartment with two bedrooms, a light-filled living room and a balcony. There is a kitchen for home-cooked meals and a desk for planning local outings. An easy-going base for exploring Bizerte at your own pace.', 'https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Dedicated workspace', 'ROOM TO UNWIND', '37.274', '9.873', '3', '2', '1', '135', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000002', 'Kelibia white-sand beach house', 'Kelibia', 'Coastal Escapes', 'A family-sized coastal house with an open living area and a terrace for shared meals. Three bedrooms and two bathrooms keep group stays comfortable. Enjoy the sea air, then return to a calm space with a kitchen and outdoor seating.', 'https://images.pexels.com/photos/19075385/pexels-photo-19075385.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace', 'COASTAL ESCAPE', '36.85', '11.097', '6', '3', '2', '320', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000002', 'Olive grove retreat in Cap Bon', 'Cap Bon', 'Houses', 'A simple country house with a private garden, two bedrooms and a shaded terrace. The kitchen opens onto a dining area made for long, relaxed meals. A peaceful choice for guests who prefer greenery and slower days.', 'https://images.pexels.com/photos/34653830/pexels-photo-34653830.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Garden', 'ROOM TO UNWIND', '36.773', '10.94', '4', '2', '1', '175', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000009', '02000000-0000-0000-0000-000000000001', 'Djerba palm courtyard dar', 'Djerba', 'Guesthouses / Dars', 'A courtyard guesthouse with whitewashed walls, a shared pool and shaded outdoor seating. Two bedrooms open onto a comfortable living space. Breakfast is included, and there is a kitchen for preparing light meals during your stay.', 'https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Pool|Free parking|Breakfast|Courtyard', 'COURTYARD LIVING', '33.804', '10.858', '4', '2', '2', '205', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000010', '02000000-0000-0000-0000-000000000001', 'Erriadh artists garden house', 'Erriadh, Djerba', 'Guesthouses / Dars', 'An intimate dar with a small courtyard, handmade decorative details and a quiet reading nook. Two bedrooms make it suitable for a small family or friends. Enjoy breakfast in the garden before setting out to explore the island.', 'https://images.pexels.com/photos/36156108/pexels-photo-36156108.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Breakfast|Courtyard', 'COURTYARD LIVING', '33.82', '10.855', '3', '2', '1', '165', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000011', '02000000-0000-0000-0000-000000000001', 'Houmt Souk rooftop apartment', 'Houmt Souk, Djerba', 'Apartments', 'A practical one-bedroom apartment with its own rooftop sitting area. Inside, a compact kitchen and comfortable sofa make short stays easy. The terrace is a lovely place to enjoy the evening air after a day out.', 'https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Dedicated workspace', 'ROOM TO UNWIND', '33.875', '10.858', '2', '1', '1', '120', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000012', '02000000-0000-0000-0000-000000000001', 'Tozeur palm garden lodge', 'Tozeur', 'Guesthouses / Dars', 'A restful guesthouse with brick details, shaded seating and a shared garden pool. Two bedrooms and a relaxed lounge provide space for a small group. Breakfast is included; local activities and transport should be arranged separately.', 'https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Pool|Free parking|Breakfast|Courtyard', 'COURTYARD LIVING', '33.915', '8.133', '4', '2', '2', '195', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000013', '02000000-0000-0000-0000-000000000001', 'Douz desert courtyard stay', 'Douz', 'Guesthouses / Dars', 'A quiet guesthouse with an enclosed courtyard and comfortable rooms. Breakfast is served in the shared dining space, with tea available in the sitting area. A calm place to rest before or after independently arranged desert outings.', 'https://images.pexels.com/photos/36156108/pexels-photo-36156108.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Breakfast|Courtyard', 'COURTYARD LIVING', '33.456', '9.025', '3', '2', '1', '150', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000014', '02000000-0000-0000-0000-000000000001', 'Matmata stone and shade guesthouse', 'Matmata', 'Guesthouses / Dars', 'A characterful guesthouse with sheltered outdoor seating and a simple, comfortable lounge. Two bedrooms provide a restful base for a small group. Enjoy a relaxed breakfast and take time to discover the surrounding region at your own pace.', 'https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Breakfast|Courtyard', 'COURTYARD LIVING', '33.543', '9.971', '4', '2', '1', '160', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000015', '02000000-0000-0000-0000-000000000002', 'Sousse medina loft', 'Sousse', 'Apartments', 'A thoughtfully arranged loft with a reading corner, a small kitchen and a comfortable sleeping area. Warm textures and local decorative details give the space its character. A good fit for guests who enjoy independent city stays.', 'https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Dedicated workspace', 'ROOM TO UNWIND', '35.825', '10.638', '2', '1', '1', '140', '30', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000016', '02000000-0000-0000-0000-000000000002', 'Skanes pool villa', 'Monastir', 'Houses', 'A spacious villa with a private pool, three bedrooms and a terrace for outdoor meals. The living room and kitchen are designed for sharing time together. Free parking and air conditioning help make family stays comfortable.', 'https://images.pexels.com/photos/31751031/pexels-photo-31751031.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Pool|Free parking', 'ROOM TO UNWIND', '35.765', '10.774', '6', '3', '2', '350', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000017', '02000000-0000-0000-0000-000000000002', 'Mahdia white terrace apartment', 'Mahdia', 'Coastal Escapes', 'A two-bedroom coastal apartment with a sunny terrace and a relaxed living area. Prepare breakfast in the kitchen and enjoy it outside when the weather allows. The simple layout works well for a couple or a small family.', 'https://images.pexels.com/photos/19075385/pexels-photo-19075385.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace', 'COASTAL ESCAPE', '35.506', '11.066', '4', '2', '1', '210', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000018', '02000000-0000-0000-0000-000000000002', 'Tabarka pine garden cottage', 'Tabarka', 'Houses', 'A cosy cottage with wood accents, a garden and a sheltered dining terrace. Two bedrooms, a kitchen and a comfortable lounge offer a calm base for a slower break. Bring a book and make time for the surrounding greenery.', 'https://images.pexels.com/photos/12998902/pexels-photo-12998902.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/5824531/pexels-photo-5824531.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Garden', 'ROOM TO UNWIND', '36.953', '8.758', '4', '2', '1', '185', '50', '20', '0', '0', 'PUBLISHED', false),
  ('11000000-0000-0000-0000-000000000019', '02000000-0000-0000-0000-000000000002', 'Ain Draham forest cottage', 'Ain Draham', 'Houses', 'A compact cottage with warm interiors and a quiet garden. This archived demonstration listing remains visible to its host for management history and is unavailable for booking.', 'https://images.pexels.com/photos/12998902/pexels-photo-12998902.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6312353/pexels-photo-6312353.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/12700517/pexels-photo-12700517.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/6264406/pexels-photo-6264406.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/2227774/pexels-photo-2227774.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace|Garden', 'ROOM TO UNWIND', '36.773', '8.686', '4', '2', '1', '170', '50', '20', '0', '0', 'DRAFT', true),
  ('11000000-0000-0000-0000-000000000020', '00000000-0000-0000-0000-000000000002', 'Nabeul ceramics courtyard house', 'Nabeul', 'Guesthouses / Dars', 'A courtyard house with local ceramics, two bedrooms and a sheltered dining area. This draft is being prepared for publication; its host can finish the description, amenities and availability before welcoming guests.', 'https://images.pexels.com/photos/36156108/pexels-photo-36156108.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/19199957/pexels-photo-19199957.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1454806/pexels-photo-1454806.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&w=1200|https://images.pexels.com/photos/8484841/pexels-photo-8484841.jpeg?auto=compress&cs=tinysrgb&w=1200', 'Wi-Fi|Kitchen|Air conditioning|Terrace', 'DRAFT', '36.456', '10.738', '4', '2', '2', '215', '50', '20', '0', '0', 'DRAFT', false)
