INSERT INTO stayora.reservations (id,property_id,guest_id,check_in,check_out,guests,nightly_price,subtotal,cleaning_fee,service_fee,total,status,payment_status,created_at) SELECT '23000000-0000-0000-0000-000000000002',id,'01000000-0000-0000-0000-000000000004',CURRENT_DATE+32,CURRENT_DATE+35,2,nightly_price,nightly_price*3,cleaning_fee,service_fee,nightly_price*3+cleaning_fee+service_fee,'DECLINED','SIMULATED_REFUNDED',now()-interval '1 day' FROM stayora.properties WHERE id='11000000-0000-0000-0000-000000000002' ON CONFLICT DO NOTHING;
