INSERT INTO stayora.availability_blocks (id,property_id,start_date,end_date,reason) SELECT ('31000000'||substr(id::text,9))::uuid,id,CURRENT_DATE+38,CURRENT_DATE+41,'Scheduled maintenance and garden care' FROM stayora.properties WHERE id BETWEEN '11000000-0000-0000-0000-000000000001' AND '11000000-0000-0000-0000-000000000008' ON CONFLICT DO NOTHING;
INSERT INTO stayora.nightly_prices (id,property_id,date,nightly_price) SELECT ('32000000-0000-0000-0000-'||lpad((right(p.id::text,12)::int*2+n)::text,12,'0'))::uuid,p.id,CURRENT_DATE+7+n,round(p.nightly_price*1.15,3) FROM stayora.properties p CROSS JOIN generate_series(0,1) n WHERE p.id BETWEEN '11000000-0000-0000-0000-000000000001' AND '11000000-0000-0000-0000-000000000018' ON CONFLICT DO NOTHING;
INSERT INTO stayora.wishlist_entries (id,account_id,property_id) SELECT ('41000000'||substr(id::text,9))::uuid,'00000000-0000-0000-0000-000000000001'::uuid,id FROM stayora.properties WHERE id IN ('11000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000003','11000000-0000-0000-0000-000000000009','11000000-0000-0000-0000-000000000012','11000000-0000-0000-0000-000000000016','11000000-0000-0000-0000-000000000018') ON CONFLICT DO NOTHING;
