WITH samples AS (SELECT p.*, n, '00000000-0000-0000-0000-000000000001'::uuid AS default_guest FROM stayora.properties p CROSS JOIN generate_series(0,2) n WHERE p.id BETWEEN '11000000-0000-0000-0000-000000000001' AND '11000000-0000-0000-0000-000000000018')
SELECT ('21000000-0000-0000-0000-' || lpad(((right(id::text,12)::int-1)*3+n+1)::text,12,'0'))::uuid, id,
 CASE WHEN n=0 AND (right(id::text,12)::int % 3=1 OR right(id::text,12)::int=2) THEN default_guest ELSE ('01000000-0000-0000-0000-'||lpad(((right(id::text,12)::int+n)%14+1)::text,12,'0'))::uuid END,
 CURRENT_DATE-(12+n*18), CURRENT_DATE-(9+n*18), least(capacity,2+n), nightly_price, nightly_price*3, cleaning_fee, service_fee, nightly_price*3+cleaning_fee+service_fee, 'CONFIRMED','SIMULATED',now()-((16+n*18)||' days')::interval FROM samples ON CONFLICT DO NOTHING;

WITH samples (n, offset_days, status, guest_id) AS (VALUES
  (1, 2, 'CONFIRMED', '00000000-0000-0000-0000-000000000001'::uuid),
  (2, 4, 'PENDING', '01000000-0000-0000-0000-000000000002'::uuid),
  (3, 6, 'CONFIRMED', '01000000-0000-0000-0000-000000000003'::uuid),
  (4, 8, 'PENDING', '00000000-0000-0000-0000-000000000001'::uuid),
  (5, 10, 'CONFIRMED', '01000000-0000-0000-0000-000000000005'::uuid),
  (6, 12, 'CONFIRMED', '01000000-0000-0000-0000-000000000006'::uuid),
  (7, 14, 'PENDING', '01000000-0000-0000-0000-000000000007'::uuid),
  (8, 16, 'CONFIRMED', '01000000-0000-0000-0000-000000000008'::uuid),
  (9, 18, 'CONFIRMED', '00000000-0000-0000-0000-000000000001'::uuid),
  (10, 20, 'CONFIRMED', '01000000-0000-0000-0000-000000000010'::uuid),
  (11, 22, 'CONFIRMED', '01000000-0000-0000-0000-000000000011'::uuid),
  (12, 24, 'CONFIRMED', '01000000-0000-0000-0000-000000000012'::uuid))
SELECT ('22000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,p.id,s.guest_id,CURRENT_DATE+offset_days,CURRENT_DATE+offset_days+3,least(p.capacity,3),p.nightly_price,p.nightly_price*3,p.cleaning_fee,p.service_fee,p.nightly_price*3+p.cleaning_fee+p.service_fee,s.status,'SIMULATED',now()-(n||' hours')::interval FROM samples s JOIN stayora.properties p ON p.id=('11000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid ON CONFLICT DO NOTHING;

SELECT '23000000-0000-0000-0000-000000000001',id,'00000000-0000-0000-0000-000000000001'::uuid,CURRENT_DATE+5,CURRENT_DATE+8,2,nightly_price,nightly_price*3,cleaning_fee,service_fee,nightly_price*3+cleaning_fee+service_fee,'CANCELLED','SIMULATED_REFUNDED',now()-interval '5 days',now()-interval '2 days','Travel dates changed; demonstration full refund.' FROM stayora.properties WHERE id='11000000-0000-0000-0000-000000000005' ON CONFLICT DO NOTHING;

-- Only completed confirmed stays are reviewed. Four stay reviews and one guest review per property remain open.
WITH samples AS (SELECT r.*,p.host_id,right(r.id::text,12)::int n FROM stayora.reservations r JOIN stayora.properties p ON p.id=r.property_id WHERE r.id::text LIKE '21000000-%')
SELECT ('51000000'||substr(id::text,9))::uuid,property_id,guest_id,id,'STAY',host_id,
 CASE WHEN n%11=0 THEN 'needs-cleaning,welcoming' WHEN n%7=0 THEN 'slow-replies,difficult-check-in,as-described' WHEN n%3=0 THEN 'clean,welcoming,easy-check-in,as-described' ELSE 'clean,responsive,as-described' END,
 CASE WHEN n%11=0 THEN 3 WHEN n%7=0 THEN 3 WHEN n%3=0 THEN 4 ELSE 5 END,
 CASE
 WHEN n%11=0 THEN 'Good value for a short break. The living area was pleasant, though the kitchen needed a more thorough clean before we arrived.' WHEN n%7=0 THEN 'The space was comfortable, but we waited for arrival instructions and the check-in felt rushed. A clearer welcome message would help.' WHEN n%3=0 THEN 'A comfortable base with a useful kitchen and thoughtful little details. Communication was friendly and the photos gave a fair idea of the space.' WHEN n%3=1 THEN 'The courtyard was spotless and the bedrooms felt calm after a busy day. Our host shared clear arrival instructions and made us feel welcome.' ELSE 'A lovely stay with fresh linens, a well-kept space and a host who answered our questions quickly. The outdoor sitting area was a highlight.' END, check_out+interval '1 day',check_out+interval '1 day' FROM samples WHERE n NOT IN (4,12,30,48) ON CONFLICT DO NOTHING;

WITH samples AS (SELECT r.*,p.host_id,right(r.id::text,12)::int n FROM stayora.reservations r JOIN stayora.properties p ON p.id=r.property_id WHERE r.id::text LIKE '21000000-%')
SELECT ('52000000'||substr(id::text,9))::uuid,property_id,host_id,id,'GUEST',guest_id,'',CASE WHEN n%8=0 THEN 3 WHEN n%4=0 THEN 4 ELSE 5 END,
CASE WHEN n%8=0 THEN 'A pleasant visit overall. Checkout ran a little late, so agreeing the final timing earlier would make the next stay smoother.' WHEN n%3=1 THEN 'Thoughtful guests who communicated their arrival time clearly and left the space tidy. We would be happy to welcome them again.' WHEN n%3=2 THEN 'Friendly and respectful throughout the stay. They followed the house rules and checked out on time.' ELSE 'Communication was easy and the home was cared for well. Thank you for being considerate visitors.' END,check_out+interval '2 days',check_out+interval '2 days' FROM samples WHERE n%3<>0 ON CONFLICT DO NOTHING;


SELECT ('61000000'||substr(r.id::text,9))::uuid,r.property_id,r.id,r.guest_id,p.host_id,'Planning your stay at '||p.title,r.created_at,r.created_at,CASE WHEN right(r.id::text,12)::int%2=0 THEN NULL ELSE r.created_at END FROM stayora.reservations r JOIN stayora.properties p ON p.id=r.property_id WHERE r.id::text LIKE '22000000-%' ON CONFLICT DO NOTHING;
SELECT ('71000000'||substr(c.id::text,9))::uuid,c.reservation_id,c.id,c.guest_id,'Hello! We expect to arrive between 16:00 and 17:00. Is that a good time for check-in?',c.created_at+interval '5 minutes',CASE WHEN c.host_read_at IS NULL THEN NULL ELSE c.created_at+interval '10 minutes' END FROM stayora.conversations c WHERE c.id::text LIKE '61000000-%' ON CONFLICT DO NOTHING;
SELECT ('72000000'||substr(c.id::text,9))::uuid,c.reservation_id,c.id,c.host_id,'That arrival window works well. I will share the meeting point before your stay. Please let me know if your plans change.',c.created_at+interval '20 minutes',CASE WHEN right(c.id::text,12)::int%2=0 THEN NULL ELSE c.created_at+interval '30 minutes' END FROM stayora.conversations c WHERE c.id::text LIKE '61000000-%' ON CONFLICT DO NOTHING;
